          "\u56FE\u5F62\u51C6\u5907\uFF1A\u8FDE\u8282\u6298\u5C3A\u3001\u523B\u5EA6\u3001\u94C6\u9489\u3001\u8FDE\u6746\u548C\u7EB8\u53F0\u53EF\u5148\u7528\u4EE3\u7801\u753B\u51FA\uFF1B\u771F\u5B9E\u56FE\u7247\u4E0E\u8FD9\u4E9B\u4EE3\u7801\u56FE\u5F62\u5206\u522B\u6210\u5C42\uFF0C\u518D\u7EDF\u4E00\u63A7\u5236\u8FD0\u52A8\u3002",
          "\u6267\u884C\u987A\u5E8F\uFF1A\u5148\u628A\u9759\u6001\u56FE\u5F62\u6216\u7D20\u6750\u505A\u5B8C\u6574\uFF0C\u6838\u5BF9\u8F6E\u5ED3\u3001\u6784\u56FE\u548C\u5206\u5C42\uFF1B\u786E\u8BA4\u6BCF\u4E2A\u72EC\u7ACB\u5BF9\u8C61\u540E\uFF0C\u518D\u6309\u4E0B\u65B9\u6B65\u9AA4\u7F16\u6392\u8FD0\u52A8\u3002\u80FD\u7528\u4EE3\u7801\u51C6\u786E\u7ED8\u5236\u7684\u5C3A\u5B50\u3001\u66F2\u7EBF\u548C\u51E0\u4F55\u4F53\uFF0C\u53EF\u5148\u753B\u6210\u4EE3\u7801\u56FE\u5F62\uFF0C\u4E0D\u8981\u6C42\u5168\u90E8\u6539\u6210\u56FE\u7247\u3002"
